import Foundation
import DHCore
import DHWorld
public struct RadioTower:Identifiable,Codable,Sendable,Equatable { public let id:EntityID; public var name:String; public var x:Double; public var y:Double; public var rangeKM:Double; public var repaired:Bool; public init(id:EntityID=UUID(),name:String,x:Double,y:Double,rangeKM:Double,repaired:Bool=false){self.id=id;self.name=name;self.x=x;self.y=y;self.rangeKM=rangeKM;self.repaired=repaired} }
public struct Broadcast:Identifiable,Codable,Sendable,Equatable { public let id:EntityID; public var tick:UInt64; public var station:String; public var text:String; public var eventKind:String?; public init(id:EntityID=UUID(),tick:UInt64,station:String,text:String,eventKind:String?=nil){self.id=id;self.tick=tick;self.station=station;self.text=text;self.eventKind=eventKind} }
public struct RadioNetwork:Codable,Sendable,Equatable { public var towers:[RadioTower]=[]; public var broadcasts:[Broadcast]=[]; public init(towers:[RadioTower]=[],broadcasts:[Broadcast]=[]){self.towers=towers;self.broadcasts=broadcasts}; public func signal(x:Double,y:Double)->Double { towers.filter(\.repaired).map{max(0,1-hypot($0.x-x,$0.y-y)/max(0.1,$0.rangeKM))}.max() ?? 0 }; public mutating func ingest(_ event:WorldEvent){let text:String;switch event.kind{case "convoy.disrupted":text="Northbound convoy overdue. Traders report shortages ahead.";case "power.restored":text="Grid power has returned to a Blackridge district.";default:text="Road report: \(event.detail)"};broadcasts.append(.init(tick:event.tick,station:"KBRG 88.7",text:text,eventKind:event.kind))} }
